10	// 本文件实现阶梯客户按月生效的方案变更：登记（plan change）与查询
11	// （plan schedule）。变更自生效月（UTC 自然月，含）起改用目标方案，
12	// 直到下一次变更；生效月之前的月份不受影响，用于续期时采用新价格而
13	// 不重算历史账单。变更记录一旦写入永不修改，不产生账后流水事件，
14	// 也不占用全局操作序号。固定单价客户与方案规则本身仍不可修改。
15	
16	func cmdPlanChange(dir, customerID, month, planID, reason string) error {
17		if !validMonth(month) {
18			return fmt.Errorf("生效月份 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", month)
19		}
20		if strings.TrimSpace(reason) == "" {
21			return fmt.Errorf("变更原因不能为空")
22		}
23	
24		s, err := loadStore(dir)
25		if err != nil {
26			return err
27		}
28		cust, ok := s.Customers[customerID]
29		if !ok {
30			return fmt.Errorf("客户标识 %q 不存在", customerID)
31		}
32		if cust.PlanID == "" {
33			return fmt.Errorf("客户 %s 是固定单价客户，未绑定阶梯方案，不能登记方案变更", customerID)
34		}
35		p, ok := s.Plans[planID]
36		if !ok {
37			return fmt.Errorf("目标方案标识 %q 不存在", planID)
38		}
39	
40		key := planChangeKey(customerID, month)
41		if existing, ok := s.PlanChanges[key]; ok {
42			// 以客户与生效月共同标识一项变更：相同目标方案与原因的重放返回
43			// 原记录，不重复生效——即使后来追加了变更或相关月份已封账；
44			// 同一项内容不同则拒绝，已有变更不可改写。
45			if existing.PlanID == planID && existing.Reason == reason {
46				fmt.Fprintf(stdout, "客户 %s 在 %s 的方案变更已存在且内容相同，返回原记录（不重复生效）：\n\n", customerID, month)
47				printPlanChange(existing, s)
48				return nil
49			}
50			return fmt.Errorf("客户 %s 在 %s 已登记方案变更（目标方案 %q，原因 %q），内容不同，已有变更不可改写",
51				customerID, month, existing.PlanID, existing.Reason)
52		}
53	
54		// 新变更只能按生效月递增追加。
55		for _, ch := range s.PlanChanges {
56			if ch.CustomerID == customerID && ch.Month >= month {
57				return fmt.Errorf("客户 %s 已存在生效月 %s 的变更，新生效月 %s 必须更晚（新变更只能按生效月递增追加）",
58					customerID, ch.Month, month)
59			}
60		}
61		// 生效月须晚于该客户所有已封账月份：已封账账单的计费结果不受影响。
62		for _, b := range s.Bills {
63			if b.CustomerID == customerID && b.Month >= month {
64				return fmt.Errorf("客户 %s 的 %s 已封账，生效月 %s 须晚于该客户所有已封账月份", customerID, b.Month, month)
65			}
66		}
67		// 登记前预检：生效月起已导入的有效（未撤回）用量（上述检查已保证这些
68		// 月份均未封账）按目标方案逐条从零计价，任一条金额溢出则整项拒绝并
69		// 指出用量，不修改用量；已撤回记录不参与预检。月累计溢出仍由结算把关
70		// （拒绝且不封账）。
71		var ids []string
72		for _, u := range s.Usage {
73			if s.isWithdrawn(u.ID) {
74				continue
75			}
76			if u.CustomerID == customerID && utcMonth(u.Time) >= month {
77				ids = append(ids, u.ID)
78			}
79		}
80		sort.Strings(ids)
81		for _, id := range ids {
82			u := s.Usage[id]
83			rec := *u
84			if _, err := tieredPrice(p.Tiers, []*usageRecord{&rec}); err != nil {
85				return fmt.Errorf("用量 %s（%s，数量 %d）按目标方案 %q 单条从零计价失败：%v；整项变更拒绝，用量未修改",
86					u.ID, utcMonth(u.Time), u.Quantity, planID, err)
87			}
88		}
89	
90		ch := &planChange{
91			CustomerID: customerID,
92			Month:      month,
93			PlanID:     planID,
94			Reason:     reason,
95			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
96		}
97		s.PlanChanges[key] = ch
98	
99		// 变更整体原子落盘后才报告成功；保存失败则一切不生效，
100		// 该客户该月份不被占用，可重试。
101		if err := s.save(); err != nil {
102			delete(s.PlanChanges, key)
103			return err
104		}
105		fmt.Fprintf(stdout, "已登记方案变更：客户 %s 自 %s（UTC 自然月，含）起改用方案 %q（%s），之前月份不受影响：\n\n",
106			customerID, month, planID, p.Name)
107		printPlanChange(ch, s)
108		return nil
109	}
110	
111	// printPlanChange 输出一条方案变更记录。
112	func printPlanChange(ch *planChange, s *state) {
113		p := s.Plans[ch.PlanID] // 载入时已校验存在
114		fmt.Fprintf(stdout, "客户：%s\n", ch.CustomerID)
115		fmt.Fprintf(stdout, "生效月：%s（UTC 自然月，含；之前月份不受影响）\n", ch.Month)
116		fmt.Fprintf(stdout, "目标方案：%s（%s）：月费 %d 分，规则 %s\n", p.ID, p.Name, p.MonthlyFee, formatTiers(p.Tiers))
117		fmt.Fprintf(stdout, "原因：%s\n", ch.Reason)
118	}
119	
120	func cmdPlanSchedule(dir, customerID, month string, hasMonth bool) error {
121		if hasMonth && !validMonth(month) {
122			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", month)
123		}
124	
125		s, err := loadStore(dir)
126		if err != nil {
127			return err
128		}
129		cust, ok := s.Customers[customerID]
130		if !ok {
131			return fmt.Errorf("客户标识 %q 不存在", customerID)
132		}
133	
134		// 只读查询：不改写数据、不占用序号、不新增记录。
135		if cust.PlanID == "" {
136			fmt.Fprintf(stdout, "客户 %s（%s）是固定单价客户（单价 %d 分），无阶梯方案安排\n",
137				cust.ID, cust.Name, cust.Price)
138			return nil
139		}
140		initial := s.Plans[cust.PlanID] // 载入时已校验存在
141		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
142		fmt.Fprintf(stdout, "初始方案：%s（%s）：月费 %d 分，规则 %s（创建时绑定，永久保留）\n",
143			initial.ID, initial.Name, initial.MonthlyFee, formatTiers(initial.Tiers))
144		changes := s.planChangesFor(customerID)
145		if len(changes) == 0 {
146			fmt.Fprintln(stdout, "方案变更：无")
147		} else {
148			fmt.Fprintln(stdout, "方案变更（按生效月升序）：")
149			for i, ch := range changes {
150				p := s.Plans[ch.PlanID] // 载入时已校验存在
151				fmt.Fprintf(stdout, "  %d. 自 %s 起改用 %s（%s）：月费 %d 分，规则 %s，原因：%s\n",
152					i+1, ch.Month, p.ID, p.Name, p.MonthlyFee, formatTiers(p.Tiers), ch.Reason)
153			}
154		}
155		if hasMonth {
156			p := s.Plans[s.effectivePlanID(cust, month)] // 载入时已校验存在
157			fmt.Fprintf(stdout, "月份 %s 的有效方案：%s（%s）：月费 %d 分，规则 %s\n", month, p.ID, p.Name, p.MonthlyFee, formatTiers(p.Tiers))
158		}
159		return nil
160	}
