1194	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1195	// 只有完整保存成功后调用方才会向用户报告成功。
1196	func (s *state) save() error {
1197		if err := s.validate(); err != nil {
1198			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1199		}
1200		data, err := json.MarshalIndent(s, "", "  ")
1201		if err != nil {
1202			return fmt.Errorf("序列化数据失败: %w", err)
1203		}
1204		data = append(data, '\n')
1205	
1206		tmp := s.path + ".tmp"
1207		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1208		if err != nil {
1209			return fmt.Errorf("写入临时数据文件失败: %w", err)
1210		}
1211		if _, err := f.Write(data); err != nil {
1212			f.Close()
1213			os.Remove(tmp)
1214			return fmt.Errorf("写入临时数据文件失败: %w", err)
1215		}
1216		if err := f.Sync(); err != nil {
1217			f.Close()
1218			os.Remove(tmp)
1219			return fmt.Errorf("同步数据文件失败: %w", err)
1220		}
1221		if err := f.Close(); err != nil {
1222			os.Remove(tmp)
1223			return fmt.Errorf("关闭数据文件失败: %w", err)
1224		}
1225		if err := os.Rename(tmp, s.path); err != nil {
1226			os.Remove(tmp)
1227			return fmt.Errorf("替换数据文件失败: %w", err)
1228		}
1229		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1230			dir.Sync()
1231			dir.Close()
1232		}
1233		return nil
1234	}
1235	
1236	func billKey(customerID, month string) string {
1237		return customerID + "|" + month
1238	}
1239	
1240	func planChangeKey(customerID, month string) string {
1241		return customerID + "|" + month
1242	}
1243	
1244	func suspensionKey(customerID, startMonth string) string {
1245		return customerID + "|" + startMonth
1246	}
1247	
1248	// monthInRange 判定月份 m 是否落在左闭右开区间 [start, end) 内。
1249	// 月份均为已校验的 YYYY-MM，字典序即时间序。
1250	func monthInRange(m, start, end string) bool {
1251		return m >= start && m < end
1252	}
1253	
1254	// suspensionsFor 返回某客户的全部暂停区间，按起月升序。
1255	func (s *state) suspensionsFor(customerID string) []*suspension {
1256		var list []*suspension
1257		for _, su := range s.Suspensions {
1258			if su.CustomerID == customerID {
1259				list = append(list, su)
1260			}
1261		}
1262		sort.Slice(list, func(i, j int) bool { return list[i].StartMonth < list[j].StartMonth })
1263		return list
1264	}
1265	
1266	// suspensionResumeKey 与 suspensionKey 相同：提前恢复以客户与目标暂停的原
1267	// 起月共同标识，一项目暂停至多一条恢复记录。
1268	func suspensionResumeKey(customerID, startMonth string) string {
1269		return customerID + "|" + startMonth
1270	}
1271	
1272	// suspensionResumeOf 返回某项暂停的提前恢复登记；未登记时返回 nil。
1273	func (s *state) suspensionResumeOf(su *suspension) *suspensionResume {
1274		return s.SuspensionResumes[suspensionResumeKey(su.CustomerID, su.StartMonth)]
1275	}
1276	
1277	// suspensionEffectiveEnd 返回某项暂停的当前有效结束月（不含）：登记提前
1278	// 恢复后为恢复月，否则为原结束月。原暂停区间与原因永久保留，本函数只决定
1279	// 当前仍受暂停限制的月份范围 [原起月, 有效结束月)。
1280	func (s *state) suspensionEffectiveEnd(su *suspension) string {
1281		if r := s.suspensionResumeOf(su); r != nil {
1282			return r.ResumeMonth
1283		}
1284		return su.EndMonth
1285	}
1286	
1287	// isSuspendedMonth 报告某客户的指定 UTC 自然月是否处于任一暂停的当前有效
1288	// 区间内（区间包含原起月、不包含当前有效结束月；相接区间视为连续暂停）。
1289	// 提前恢复释放的月份不再受该项暂停限制。
1290	func (s *state) isSuspendedMonth(customerID, month string) bool {
1291		for _, su := range s.Suspensions {
1292			if su.CustomerID == customerID && monthInRange(month, su.StartMonth, s.suspensionEffectiveEnd(su)) {
1293				return true
1294			}
1295		}
1296		return false
1297	}
1298	
1299	// planChangesFor 返回某客户的全部方案变更，按生效月升序。
1300	func (s *state) planChangesFor(customerID string) []*planChange {
1301		var list []*planChange
1302		for _, ch := range s.PlanChanges {
1303			if ch.CustomerID == customerID {
1304				list = append(list, ch)
1305			}
1306		}
1307		sort.Slice(list, func(i, j int) bool { return list[i].Month < list[j].Month })
1308		return list
1309	}
1310	
1311	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
1312	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次变更替换。
1313	func (s *state) effectivePlanID(cust *customer, month string) string {
1314		planID := cust.PlanID
1315		latest := ""
1316		for _, ch := range s.PlanChanges {
1317			if ch.CustomerID == cust.ID && ch.Month <= month && ch.Month >= latest {
1318				latest = ch.Month
1319				planID = ch.PlanID
1320			}
1321		}
1322		return planID
1323	}
1324	
1325	// sealed 报告某客户的指定月份是否已封账。
1326	func (s *state) sealed(customerID, month string) bool {
1327		_, ok := s.Bills[billKey(customerID, month)]
1328		return ok
1329	}
1330	
1331	// isWithdrawn 报告指定用量标识是否已撤回。已撤回用量不参与结算、方案变更
1332	// 预检与暂停区间冲突检查，但原记录永久保留并继续参与导入判重。
1333	func (s *state) isWithdrawn(usageID string) bool {
1334		_, ok := s.Withdrawals[usageID]
1335		return ok
1336	}
1337	
1338	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
1339	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
1340		var list []*adjustment
1341		for _, a := range s.Adjustments {
1342			if a.CustomerID == customerID && a.Month == month {
1343				list = append(list, a)
1344			}
1345		}
1346		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1347		return list
1348	}
1349	
1350	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
1351	func correctionsFor(s *state, paymentID string) []*correction {
1352		var list []*correction
1353		for _, c := range s.Corrections {
1354			if c.PaymentID == paymentID {
1355				list = append(list, c)
1356			}
1357		}
1358		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1359		return list
1360	}
1361	
1362	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
1363	// 原始分配，否则为序号最大（最新）的更正的分配。
1364	func currentAllocations(s *state, p *payment) []paymentAllocation {
1365		var latest *correction
1366		for _, c := range s.Corrections {
1367			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
1368				latest = c
1369			}
1370		}
1371		if latest != nil {
1372			return latest.Allocations
1373		}
1374		return p.Allocations
1375	}
1376	
1377	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
1378	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
1379		for _, al := range allocs {
1380			if al.Month == month {
1381				return al.Amount
1382			}
1383		}
1384		return 0
1385	}
1386	
1387	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
1388	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
1389	func paymentsEverFor(s *state, customerID, month string) []*payment {
1390		var list []*payment
1391		for _, p := range s.Payments {
1392			if p.CustomerID != customerID {
1393				continue
1394			}
1395			involved := p.amountFor(month) > 0
1396			if !involved {
1397				for _, c := range s.Corrections {
1398					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1399						involved = true
1400						break
1401					}
1402				}
1403			}
1404			if involved {
1405				list = append(list, p)
1406			}
1407		}
1408		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1409		return list
1410	}
1411	
1412	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入并扣除退款后
1413	// 的实收之和。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1414	// 累加，溢出时返回错误。
1415	func paymentReceived(s *state, customerID, month string) (int64, error) {
1416		var received int64
1417		for _, p := range s.Payments {
1418			if p.CustomerID != customerID || p.Revoked {
1419				continue
1420			}
1421			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1422			if amt <= 0 {
1423				continue
1424			}
1425			var err error
1426			received, err = add64(received, amt)
1427			if err != nil {
1428				return 0, err
1429			}
1430		}
1431		return received, nil
1432	}
1433	
1434	// refundsFor 返回某收款的全部退款，按操作序号升序。
1435	func refundsFor(s *state, paymentID string) []*refund {
1436		var list []*refund
1437		for _, r := range s.Refunds {
1438			if r.PaymentID == paymentID {
1439				list = append(list, r)
1440			}
1441		}
1442		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1443		return list
1444	}
1445	
1446	// refundedForMonth 返回某收款在指定月份的累计退款金额（分）；无退款时为 0。
1447	// 数据在载入时已校验累计不超退，合计不超过该月分配，不会溢出。
1448	func refundedForMonth(s *state, paymentID, month string) int64 {
1449		var total int64
1450		for _, r := range s.Refunds {
1451			if r.PaymentID == paymentID {
1452				total += allocAmountFor(r.Allocations, month)
1453			}
1454		}
1455		return total
1456	}
1457	
1458	// paymentHasRefunds 报告某收款是否已发生退款。首次退款后该收款的最新分配
1459	// 固定，不得再新增分配更正或整笔撤销。
1460	func paymentHasRefunds(s *state, paymentID string) bool {
1461		for _, r := range s.Refunds {
1462			if r.PaymentID == paymentID {
1463				return true
1464			}
1465		}
1466		return false
1467	}
1468	
1469	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1470	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1471	
1472	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1473	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1474	// [0, 有符号 64 位最大值] 内，全程整数运算。
1475	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1476		var amounts []int64
1477		for _, a := range adjs {
1478			if !a.Revoked {
1479				amounts = append(amounts, a.Amount)
1480			}
1481		}
1482		net, err = sumSigned64(amounts...)
1483		if err != nil {
1484			return 0, 0, err
1485		}
1486		payable, err = addSigned64(b.TotalFee, net)
1487		if err != nil {
1488			return 0, 0, err
1489		}
1490		if payable < 0 {
1491			return 0, 0, errPayableOutOfRange
1492		}
1493		return net, payable, nil
1494	}
1495

