242		if err != nil {
243			return err
244		}
245	
246		s, err := loadStore(dir)
247		if err != nil {
248			return err
249		}
250		if _, exists := s.Customers[id]; exists {
251			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
252		}
253		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
254		if err := s.save(); err != nil {
255			return err
256		}
257		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
258		return nil
259	}
