261	func parsePrice(text string) (int64, error) {
262		text = strings.TrimSpace(text)
263		price, err := strconv.ParseInt(text, 10, 64)
264		if err != nil {
265			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
266		}
267		if price < 0 {
268			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
269		}
270		return price, nil
271	}
