280	func cmdUsageImport(dir, file string) error {
281		var reader io.ReadCloser
282		var source string
283		if file == "-" {
284			reader = io.NopCloser(os.Stdin)
285			source = "标准输入"
286		} else {
287			f, err := os.Open(file)
288			if err != nil {
289				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
290			}
291			reader = f
292			source = file
293		}
294		defer reader.Close()
295	
296		rows, parseErrs := parseUsageFile(reader)
297	
298		s, err := loadStore(dir)
299		if err != nil {
300			return err
301		}
302	
303		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
304		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
305		var problems []string
306		problems = append(problems, parseErrs...)
307	
308		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
309		var ordered []*parsedRow
310		newCount, dupCount := 0, 0
311	
312		for _, r := range rows {
313			cust, ok := s.Customers[r.rec.CustomerID]
314			if !ok {
315				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
316				continue
317			}
318	
319			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
320			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
321			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
322			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
323			var existing *usageRecord
324			if inStore, ok := s.Usage[r.rec.ID]; ok {
325				existing = inStore
326			} else if inBatch, ok := accepted[r.rec.ID]; ok {
327				existing = &inBatch.rec
328			}
329			if existing != nil {
330				if !sameUsage(existing, &r.rec, r.t) {
331					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
332						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
333					continue
334				}
335				dupCount++
336				continue
337			}
338	
339			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
340			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
341			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
342			rowMonth := r.t.UTC().Format("2006-01")
343			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
344				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
345					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
346				continue
347			}
348			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
349			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
350			// 溢出（金额单位：分）。
351			if cust.PlanID == "" {
352				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
353					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
354					continue
355				}
356			} else {
357				rec := r.rec
358				planID := s.effectivePlanID(cust, rowMonth)
359				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
360					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
361					continue
362				}
363			}
364	
365			// 全新标识：不得进入该客户已封账的 UTC 自然月。
366			if s.sealed(r.rec.CustomerID, rowMonth) {
367				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
368					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
369				continue
370			}
371	
372			rr := r
373			accepted[r.rec.ID] = rr
374			ordered = append(ordered, rr)
375			newCount++
376		}
377	
378		if len(problems) > 0 {
379			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
380		}
381	
382		for _, r := range ordered {
383			rec := r.rec
384			s.Usage[rec.ID] = &rec
385		}
386		if err := s.save(); err != nil {
387			return err
388		}
389		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
390		return nil
391	}
