393	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
394	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
395		cr := csv.NewReader(r)
396		cr.FieldsPerRecord = 4
397		cr.TrimLeadingSpace = true
398	
399		header, err := cr.Read()
400		if err == io.EOF {
401			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
402		}
403		if err != nil {
404			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
405		}
406		for i := range header {
407			header[i] = strings.TrimSpace(header[i])
408		}
409		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
410			header[2] != "time" || header[3] != "quantity" {
411			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
412		}
413	
414		var rows []*parsedRow
415		var problems []string
416		line := 1
417		for {
418			rec, err := cr.Read()
419			if err == io.EOF {
420				break
421			}
422			line++
423			if err != nil {
424				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
425				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
426					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
427					break
428				}
429				continue
430			}
431			for i := range rec {
432				rec[i] = strings.TrimSpace(rec[i])
433			}
434	
435			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
436			if id == "" {
437				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
438				continue
439			}
440			if custID == "" {
441				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
442				continue
443			}
444			t, err := time.Parse(time.RFC3339, ts)
445			if err != nil {
446				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
447				continue
448			}
449			qty, err := strconv.ParseInt(qtyText, 10, 64)
450			if err != nil {
451				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
452				continue
453			}
454			if qty <= 0 {
455				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
456				continue
457			}
458	
459			rows = append(rows, &parsedRow{
460				line: line,
461				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
462				t:    t,
463			})
464		}
465		return rows, problems
466	}
