468	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
469	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
470	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
471		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
472			return false
473		}
474		et, err := time.Parse(time.RFC3339, existing.Time)
475		if err != nil {
476			return existing.Time == candidate.Time
477		}
478		return et.Equal(candidateT)
479	}
