481	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
482	func validMonth(m string) bool {
483		t, err := time.Parse("2006-01", m)
484		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
485			return false
486		}
487		return true
488	}
489	
490	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
491	func inMonth(rfc3339, month string) bool {
492		t, err := time.Parse(time.RFC3339, rfc3339)
493		if err != nil {
494			return false
495		}
496		return t.UTC().Format("2006-01") == month
497	}
498	
499	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
500	// 入参时间均已在载入/导入时校验为 RFC3339。
501	func utcMonth(rfc3339 string) string {
502		t, _ := time.Parse(time.RFC3339, rfc3339)
503		return t.UTC().Format("2006-01")
504	}
