506	func cmdBillSettle(dir, customerID, month string) error {
507		if !validMonth(month) {
508			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
509		}
510		s, err := loadStore(dir)
511		if err != nil {
512			return err
513		}
514		cust, ok := s.Customers[customerID]
515		if !ok {
516			return fmt.Errorf("客户标识 %q 不存在", customerID)
517		}
518	
519		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
520		if s.isSuspendedMonth(customerID, month) {
521			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
522		}
523	
524		key := billKey(customerID, month)
525		if existing, ok := s.Bills[key]; ok {
526			// 幂等：同一客户同一月份重复结算，直接返回原账单，
527			// 不重新计费、不产生新账单或调整、不落盘。
528			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
529			printBill(existing, cust, s)
530			return nil
531		}
532	
533		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
534		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
535		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
536		// 结算且不封账。
537		inMonthRecs := monthUsage(s, customerID, month)
538		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
539			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
540		}
541	
542		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
543		if cust.PlanID != "" {
544			return settleTiered(s, cust, month, inMonthRecs)
545		}
546	
547		b, err := buildFixedBill(cust, month, inMonthRecs)
548		if err != nil {
549			return fmt.Errorf("%v，拒绝结算且不封账", err)
550		}
551		s.Bills[key] = b
552	
553		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
554		if err := s.save(); err != nil {
555			delete(s.Bills, key)
556			return err
557		}
558		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
559		printBill(b, cust, s)
560		return nil
561	}
