601	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
602	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
603	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
604		lines := make([]billLine, 0, len(recs))
605		var totalQty, totalFee int64
606		for _, u := range recs {
607			lineFee, err := mul64(u.Quantity, cust.Price)
608			if err != nil {
609				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
610			}
611			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
612				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
613			}
614			if totalFee, err = add64(totalFee, lineFee); err != nil {
615				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
616			}
617			lines = append(lines, billLine{
618				UsageID:  u.ID,
619				Time:     u.Time,
620				Quantity: u.Quantity,
621				LineFee:  lineFee,
622			})
623		}
624		return &bill{
625			ID:         stableBillID(cust.ID, month),
626			CustomerID: cust.ID,
627			Month:      month,
628			TotalQty:   totalQty,
629			UnitPrice:  cust.Price,
630			TotalFee:   totalFee,
631			Lines:      lines,
632			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
633		}, nil
634	}
