636	func sortByInstant(us []*usageRecord) {
637		// 入参时间均已在载入/导入时校验为 RFC3339。
638		sort.Slice(us, func(i, j int) bool {
639			ti, _ := time.Parse(time.RFC3339, us[i].Time)
640			tj, _ := time.Parse(time.RFC3339, us[j].Time)
641			ui, uj := ti.UTC(), tj.UTC()
642			if !ui.Equal(uj) {
643				return ui.Before(uj)
644			}
645			return us[i].ID < us[j].ID
646		})
647	}
