664		if tiered {
665			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
666			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
667			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
