672				} else {
673					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
674				}
675			}
676		} else {
677			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
678		}
679		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
680		if tiered {
681			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
682			// 月费不计入总数量、各档金额或逐条小计。
683			usageFee := b.TotalFee - b.MonthlyFee
684			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
685			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
686			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
687		} else {
688			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
689		}
690		if tiered {
691			fmt.Fprintln(stdout, "各档合计：")
692			for i, tt := range b.TierTotals {
693				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
694					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
695			}
696		}
697		// 数据在载入时已校验一致，此处计算不会出错。
698		net, payable, _ := billTotals(b, adjs)
699		received, _ := paymentReceived(s, b.CustomerID, b.Month)
700		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
701		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
702		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
703		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
704		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
705		if len(b.Lines) == 0 {
706			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
707		} else {
708			fmt.Fprintln(stdout, "明细：")
709		}
710		for i, ln := range b.Lines {
711			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
712				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
713			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
714			for j, seg := range ln.Segments {
715				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
716					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
717			}
718		}
719		if len(adjs) == 0 {
720			fmt.Fprintln(stdout, "调整与撤销历史：无")
721		} else {
722			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
723			for i, ev := range historyEvents(adjs) {
724				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
725			}
726		}
727		if len(pays) == 0 {
728			fmt.Fprintln(stdout, "收款与撤销历史：无")
729		} else {
730			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
731			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
732				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
733			}
734		}
735	}
