737	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
738	func historyEvents(adjs []*adjustment) []string {
739		type event struct {
740			seq  int64
741			text string
742		}
743		var events []event
744		for _, a := range adjs {
745			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
746				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
747			if a.Revoked {
748				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
749					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
750			}
751		}
752		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
753		out := make([]string, len(events))
754		for i, ev := range events {
755			out[i] = ev.text
756		}
757		return out
758	}
759	
760	func adjustKind(amount int64) string {
761		if amount > 0 {
762			return "补收"
763		}
764		return "减免"
765	}
766	
767	func adjustStatus(a *adjustment) string {
768		if a.Revoked {
769			return "已撤销"
770		}
771		return "生效中"
772	}
