774	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
775	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
776	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
777	// 的最新分配。
778	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
779		type event struct {
780			seq  int64
781			text string
782		}
783		var events []event
784		for _, p := range pays {
785			alloc := p.amountFor(month)
786			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
787				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
788			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
789			running := alloc
790			for _, c := range correctionsFor(s, p.ID) {
791				after := allocAmountFor(c.Allocations, month)
792				if running == 0 && after == 0 {
793					continue // 本次更正不涉及本账单
794				}
795				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
796					c.ID, c.Reason, p.ID, running, after)})
797				running = after
798			}
799			if p.Revoked {
800				// 整笔撤销取消的是撤销时的最新分配。
801				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
802					p.ID, p.RevokeReason, p.ID, p.Total, running)})
803			}
804			// 退款在其发生序号减少本账单实收；退款不可撤销，记录永久保留。
805			for _, r := range refundsFor(s, p.ID) {
806				amt := allocAmountFor(r.Allocations, month)
807				if amt <= 0 {
808					continue // 本次退款不涉及本账单
809				}
810				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
811					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
812			}
813		}
814		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
815		out := make([]string, len(events))
816		for i, ev := range events {
817			out[i] = ev.text
818		}
819		return out
820	}
821	
822	func paymentStatus(p *payment) string {
823		if p.Revoked {
824			return "已撤销"
825		}
826		return "实收中"
827	}
