829	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
830	func parseAmount(text string) (int64, error) {
831		text = strings.TrimSpace(text)
832		amount, err := strconv.ParseInt(text, 10, 64)
833		if err != nil {
834			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
835		}
836		if amount == 0 {
837			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
838		}
839		return amount, nil
840	}
