842	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
843		if !validMonth(month) {
844			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
845		}
846		if strings.TrimSpace(adjID) == "" {
847			return fmt.Errorf("调整标识不能为空")
848		}
849		amount, err := parseAmount(amountText)
850		if err != nil {
851			return err
852		}
853		if strings.TrimSpace(reason) == "" {
854			return fmt.Errorf("调整原因不能为空")
855		}
856	
857		s, err := loadStore(dir)
858		if err != nil {
859			return err
860		}
861		if _, ok := s.Customers[customerID]; !ok {
862			return fmt.Errorf("客户标识 %q 不存在", customerID)
863		}
864		b, ok := s.Bills[billKey(customerID, month)]
865		if !ok {
866			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
867		}
868	
869		if existing, ok := s.Adjustments[adjID]; ok {
870			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
871			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
872			if existing.CustomerID == customerID && existing.Month == month &&
873				existing.Amount == amount && existing.Reason == reason {
874				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
875				printAdjustment(existing, s)
876				return nil
877			}
878			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
879				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
880		}
881	
882		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
883		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
884		// 不占用该调整标识。
885		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
886		if err != nil {
887			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
888		}
889		received, err := paymentReceived(s, customerID, month)
890		if err != nil {
891			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
892		}
893		newPayable, err := addSigned64(payable, amount)
894		if err != nil {
895			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
896		}
897		if newPayable < 0 {
898			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
899		}
900		if newPayable < received {
901			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
902				newPayable, received, payable, amount)
903		}
904	
905		a := &adjustment{
906			ID:         adjID,
907			CustomerID: customerID,
908			Month:      month,
909			Amount:     amount,
910			Reason:     reason,
911			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
912		}
913		s.NextSeq++
914		a.Seq = s.NextSeq
915		s.Adjustments[adjID] = a
916	
917		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
918		// 该调整标识不被占用。
919		if err := s.save(); err != nil {
920			delete(s.Adjustments, adjID)
921			s.NextSeq--
922			return err
923		}
924		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
925			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
926		printAdjustment(a, s)
927		return nil
928	}
929	
930	func cmdBillRevoke(dir, adjID, reason string) error {
931		if strings.TrimSpace(adjID) == "" {
932			return fmt.Errorf("调整标识不能为空")
933		}
934		if strings.TrimSpace(reason) == "" {
935			return fmt.Errorf("撤销原因不能为空")
936		}
937	
938		s, err := loadStore(dir)
939		if err != nil {
940			return err
941		}
942		a, ok := s.Adjustments[adjID]
943		if !ok {
944			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
945		}
946	
947		if a.Revoked {
948			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
949			// 改用其他原因则拒绝。
950			if a.RevokeReason == reason {
951				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
952				printAdjustment(a, s)
953				return nil
954			}
955			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
956		}
957	
958		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
959		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
960		// 改变余额后重试。
961		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
962		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
963		if err != nil {
964			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
965		}
966		received, err := paymentReceived(s, a.CustomerID, a.Month)
967		if err != nil {
968			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
969		}
970		neg, err := neg64(a.Amount)
971		if err != nil {
972			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
973		}
974		newPayable, err := addSigned64(payable, neg)
975		if err != nil {
976			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
977				payable, a.Amount)
978		}
979		if newPayable < 0 {
980			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
981				newPayable, payable, a.Amount)
982		}
983		if newPayable < received {
984			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
985				newPayable, received, payable, a.Amount)
986		}
987	
988		a.Revoked = true
989		a.RevokeReason = reason
990		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
991		s.NextSeq++
992		a.RevokeSeq = s.NextSeq
993	
994		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
995		if err := s.save(); err != nil {
996			a.Revoked = false
997			a.RevokeReason = ""
998			a.RevokedAt = ""
999			a.RevokeSeq = 0
1000			s.NextSeq--
1001			return err
1002		}
1003		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
1004			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
1005		printAdjustment(a, s)
1006		return nil
1007	}
