1009	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
1010	func printAdjustment(a *adjustment, s *state) {
1011		b := s.Bills[billKey(a.CustomerID, a.Month)]
1012		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
1013		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
1014		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
1015		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
1016		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
1017		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
1018		if a.Revoked {
1019			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
1020		} else {
1021			fmt.Fprintf(stdout, "当前状态：生效中\n")
1022		}
1023		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
1024	}
