1026	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
1027	func parsePositiveAmount(text string) (int64, error) {
1028		text = strings.TrimSpace(text)
1029		amount, err := strconv.ParseInt(text, 10, 64)
1030		if err != nil {
1031			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1032		}
1033		if amount <= 0 {
1034			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1035		}
1036		return amount, nil
1037	}
1038	
1039	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
1040		if !validMonth(month) {
1041			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1042		}
1043		amount, err := parsePositiveAmount(amountText)
1044		if err != nil {
1045			return err
1046		}
1047		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
1048		return registerPayment(dir, customerID, payID, amount, note,
1049			[]paymentAllocation{{Month: month, Amount: amount}})
1050	}
