1052	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1053		total, err := parsePositiveAmount(totalText)
1054		if err != nil {
1055			return err
1056		}
1057		allocs, err := parseAllocations(allocArgs)
1058		if err != nil {
1059			return err
1060		}
1061		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1062		var sum int64
1063		for _, al := range allocs {
1064			sum, err = add64(sum, al.Amount)
1065			if err != nil {
1066				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1067			}
1068		}
1069		if sum != total {
1070			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1071		}
1072		return registerPayment(dir, customerID, payID, total, note, allocs)
1073	}
