1075	// --- 自动分配汇款（bill remit-auto） ---
1076	
1077	// cmdBillRemitAuto 登记一笔自动分配汇款：调用方只提供客户、收款标识、总金额
1078	// 与备注，月份金额由工具确定——首次登记只选择该客户当前已有账单，按 UTC
1079	// 账期月升序依次偿还当前未收余额（调整、最新收款分配、撤销及退款后的净额），
1080	// 跳过余额为 0 的月份，前一月份还清后才分配下一月，最后一月可部分偿还；
1081	// 不补结算、不跨客户、不留未分配款项。无欠款或总金额超过全部欠款时整笔拒绝。
1082	func cmdBillRemitAuto(dir, customerID, payID, totalText, note string) error {
1083		total, err := parsePositiveAmount(totalText)
1084		if err != nil {
1085			return err
1086		}
1087		if strings.TrimSpace(payID) == "" {
1088			return fmt.Errorf("收款标识不能为空")
1089		}
1090		if strings.TrimSpace(note) == "" {
1091			return fmt.Errorf("收款备注不能为空")
1092		}
1093	
1094		s, err := loadStore(dir)
1095		if err != nil {
1096			return err
1097		}
1098		if _, ok := s.Customers[customerID]; !ok {
1099			return fmt.Errorf("客户标识 %q 不存在", customerID)
1100		}
1101	
1102		if existing, ok := s.Payments[payID]; ok {
1103			// 自动登记按客户、总金额、备注判重：相同请求返回原收款及当前状态，
1104			// 不写盘、不重新分配、不增加序号；已撤销或已退款的仍返回当前状态，
1105			// 不恢复旧分配或已退、已撤销金额。
1106			if existing.Auto && existing.CustomerID == customerID &&
1107				existing.Total == total && existing.Note == note {
1108				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同（自动分配登记），返回原收款及当前状态（不写盘、不重新分配、不增加序号）：\n\n", payID)
1109				printAutoPayment(s, existing)
1110				return nil
1111			}
1112			// 同一标识在自动与显式分配登记间复用拒绝；内容不同同样拒绝。
1113			if !existing.Auto {
1114				return fmt.Errorf("收款标识 %q 已由显式分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1115					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1116			}
1117			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q），拒绝复用",
1118				payID, existing.CustomerID, existing.Total, existing.Note)
1119		}
1120	
1121		// 首次登记的自动分配由 remit-auto 与整批导入共用的 autoAllocate 确定。
1122		allocs, err := autoAllocate(s, customerID, total)
1123		if err != nil {
1124			return err
1125		}
1126	
1127		// 成功保存为一笔普通收款及首次自动分配：占用一个账后全局序号，
1128		// 不按月份拆成多笔；可沿用分配更正、整笔撤销、部分退款及退款后
1129		// 固定分配的规则。
1130		p := &payment{
1131			ID:          payID,
1132			CustomerID:  customerID,
1133			Total:       total,
1134			Note:        note,
1135			Allocations: allocs,
1136			Auto:        true,
1137			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1138		}
1139		s.NextSeq++
1140		p.Seq = s.NextSeq
1141		s.Payments[payID] = p
1142	
1143		// 收款记录、首次分配与序号在同一次原子保存中持久化；保存失败则一切
1144		// 不生效，该收款标识与序号不被占用，可原样重试。
1145		if err := s.save(); err != nil {
1146			delete(s.Payments, payID)
1147			s.NextSeq--
1148			return err
1149		}
1150		fmt.Fprintf(stdout, "已按最早欠款账期自动分配并登记收款 %q（总额 %d 分，%s；一次操作，占用一个账后序号）：\n\n",
1151			payID, total, moneyFen(total))
1152		printAutoPayment(s, p)
1153		return nil
1154	}
1155	
1156	// printAutoPayment 输出一笔自动分配登记的收款：收款标识、总额、备注、当前
1157	// 状态、首次分配与最新分配，以及这两份分配所涉月份的当前余额。首次分配
1158	// 永久保留；最新分配经更正变化时以最新为准，退款与撤销不改变首次分配。
1159	func printAutoPayment(s *state, p *payment) {
1160		current := currentAllocations(s, p)
1161		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1162		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1163		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1164		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1165		if p.Revoked {
1166			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1167		} else {
1168			fmt.Fprintf(stdout, "当前状态：实收中\n")
1169		}
1170		fmt.Fprintf(stdout, "首次分配（登记时按最早欠款账期自动确定，永久保留）：%s\n", formatAllocations(p.Allocations))
1171		if sameAllocations(current, p.Allocations) {
1172			fmt.Fprintf(stdout, "最新分配：%s（与首次分配相同）\n", formatAllocations(current))
1173		} else {
1174			fmt.Fprintf(stdout, "最新分配（经更正，以最新为准）：%s\n", formatAllocations(current))
1175		}
1176		fmt.Fprintln(stdout, "首次与最新分配所涉月份当前余额：")
1177		for _, m := range unionMonths(p.Allocations, current) {
1178			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1179			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1180			received, _ := paymentReceived(s, p.CustomerID, m)
1181			fmt.Fprintf(stdout, "  月份 %s：首次分配 %d 分，最新分配 %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1182				m, allocAmountFor(p.Allocations, m), allocAmountFor(current, m),
1183				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1184		}
1185	}
1186	
1187	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1188	// 月份不得重复，每项金额为正整数分。
1189	func parseAllocations(args []string) ([]paymentAllocation, error) {
1190		if len(args) == 0 {
1191			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1192		}
1193		seen := make(map[string]bool)
1194		allocs := make([]paymentAllocation, 0, len(args))
1195		for _, arg := range args {
1196			parts := strings.Split(arg, ":")
1197			if len(parts) != 2 {
1198				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1199			}
1200			month := strings.TrimSpace(parts[0])
1201			if !validMonth(month) {
1202				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1203			}
1204			if seen[month] {
1205				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1206			}
1207			seen[month] = true
1208			amount, err := parsePositiveAmount(parts[1])
1209			if err != nil {
1210				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1211			}
1212			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1213		}
1214		return allocs, nil
1215	}
1216	
1217	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1218	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1219	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1220		if strings.TrimSpace(payID) == "" {
1221			return fmt.Errorf("收款标识不能为空")
1222		}
1223		if strings.TrimSpace(note) == "" {
1224			return fmt.Errorf("收款备注不能为空")
1225		}
1226		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1227		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1228	
1229		s, err := loadStore(dir)
1230		if err != nil {
1231			return err
1232		}
1233		if _, ok := s.Customers[customerID]; !ok {
1234			return fmt.Errorf("客户标识 %q 不存在", customerID)
1235		}
1236		for _, al := range allocs {
1237			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1238				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1239			}
1240		}
1241	
1242		if existing, ok := s.Payments[payID]; ok {
1243			// 自动与显式分配登记之间不得复用同一收款标识：标识由 bill remit-auto
1244			// 占用时，bill pay / bill remit 一律拒绝（即使内容碰巧相同）。
1245			if existing.Auto {
1246				return fmt.Errorf("收款标识 %q 已由自动分配登记占用（已有：客户=%s 总额=%d 备注=%q 分配=%s），自动与显式分配登记之间不得复用，拒绝",
1247					payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1248			}
1249			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1250			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1251			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1252			if samePaymentContent(existing, customerID, total, note, allocs) {
1253				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1254				printPayment(existing, s)
1255				return nil
1256			}
1257			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1258				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1259		}
1260	
1261		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1262		for _, al := range allocs {
1263			b := s.Bills[billKey(customerID, al.Month)]
1264			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1265			if err != nil {
1266				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1267			}
1268			received, err := paymentReceived(s, customerID, al.Month)
1269			if err != nil {
1270				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1271			}
1272			if payable == 0 {
1273				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1274			}
1275			if al.Amount > payable-received {
1276				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1277					al.Amount, payable-received, customerID, al.Month, payable, received)
1278			}
1279		}
1280	
1281		p := &payment{
1282			ID:          payID,
1283			CustomerID:  customerID,
1284			Total:       total,
1285			Note:        note,
1286			Allocations: allocs,
1287			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1288		}
1289		s.NextSeq++
1290		p.Seq = s.NextSeq
1291		s.Payments[payID] = p
1292	
1293		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1294		// 一切不生效，该收款标识不被占用。
1295		if err := s.save(); err != nil {
1296			delete(s.Payments, payID)
1297			s.NextSeq--
1298			return err
1299		}
1300		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1301		printAllocationBalances(s, p, allocs)
1302		fmt.Fprintln(stdout)
1303		printPayment(p, s)
1304		return nil
1305	}
