1307	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1308	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1309	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1310		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1311			return false
1312		}
1313		return sameAllocations(p.Allocations, allocs)
1314	}
