1316	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1317	func sameAllocations(a, b []paymentAllocation) bool {
1318		if len(a) != len(b) {
1319			return false
1320		}
1321		for _, al := range b {
1322			if allocAmountFor(a, al.Month) != al.Amount {
1323				return false
1324			}
1325		}
1326		return true
1327	}
