1329	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1330	func formatAllocations(allocs []paymentAllocation) string {
1331		parts := make([]string, len(allocs))
1332		for i, al := range allocs {
1333			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1334		}
1335		return strings.Join(parts, ",")
1336	}
