1349	func cmdBillUnpay(dir, payID, reason string) error {
1350		if strings.TrimSpace(payID) == "" {
1351			return fmt.Errorf("收款标识不能为空")
1352		}
1353		if strings.TrimSpace(reason) == "" {
1354			return fmt.Errorf("撤销原因不能为空")
1355		}
1356	
1357		s, err := loadStore(dir)
1358		if err != nil {
1359			return err
1360		}
1361		p, ok := s.Payments[payID]
1362		if !ok {
1363			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1364		}
1365	
1366		if p.Revoked {
1367			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1368			// 改用其他原因则拒绝。
1369			if p.RevokeReason == reason {
1370				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1371				printPayment(p, s)
1372				return nil
1373			}
1374			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1375		}
1376	
1377		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1378		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1379		// 处理。
1380		if paymentHasRefunds(s, payID) {
1381			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1382		}
1383	
1384		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1385		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1386		// 分配、更正与撤销原因永久保留。
1387		p.Revoked = true
1388		p.RevokeReason = reason
1389		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1390		s.NextSeq++
1391		p.RevokeSeq = s.NextSeq
1392	
1393		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1394		if err := s.save(); err != nil {
1395			p.Revoked = false
1396			p.RevokeReason = ""
1397			p.RevokedAt = ""
1398			p.RevokeSeq = 0
1399			s.NextSeq--
1400			return err
1401		}
1402		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1403		printAllocationBalances(s, p, currentAllocations(s, p))
1404		fmt.Fprintln(stdout)
1405		printPayment(p, s)
1406		return nil
1407	}
