1449	// --- 收款分配更正 ---
1450	
1451	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1452		if strings.TrimSpace(payID) == "" {
1453			return fmt.Errorf("收款标识不能为空")
1454		}
1455		if strings.TrimSpace(corrID) == "" {
1456			return fmt.Errorf("更正标识不能为空")
1457		}
1458		if strings.TrimSpace(reason) == "" {
1459			return fmt.Errorf("更正原因不能为空")
1460		}
1461		allocs, err := parseAllocations(allocArgs)
1462		if err != nil {
1463			return err
1464		}
1465		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1466		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1467	
1468		s, err := loadStore(dir)
1469		if err != nil {
1470			return err
1471		}
1472		p, ok := s.Payments[payID]
1473		if !ok {
1474			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1475		}
1476	
1477		if existing, ok := s.Corrections[corrID]; ok {
1478			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1479			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1480			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1481			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1482				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1483				printCorrection(existing, s)
1484				return nil
1485			}
1486			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1487				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1488		}
1489	
1490		// 新增更正只允许未撤销收款。
1491		if p.Revoked {
1492			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1493		}
1494	
1495		// 首次退款后该收款的最新分配固定，拒绝新增分配更正；已有更正的相同
1496		// 重放已在上面按原记录返回，不受此限。无退款的收款仍按原规则处理。
1497		if paymentHasRefunds(s, payID) {
1498			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝新增分配更正", payID)
1499		}
1500	
1501		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1502		var sum int64
1503		for _, al := range allocs {
1504			sum, err = add64(sum, al.Amount)
1505			if err != nil {
1506				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1507			}
1508		}
1509		if sum != p.Total {
1510			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1511		}
1512		// 新分配月份须是原客户的已结算账单。
1513		for _, al := range allocs {
1514			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1515				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1516			}
1517		}
1518	
1519		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1520		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1521		current := currentAllocations(s, p)
1522		for _, m := range unionMonths(current, allocs) {
1523			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1524			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1525			if err != nil {
1526				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1527			}
1528			received, err := paymentReceived(s, p.CustomerID, m)
1529			if err != nil {
1530				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1531			}
1532			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1533			received -= allocAmountFor(current, m)
1534			received, err = add64(received, allocAmountFor(allocs, m))
1535			if err != nil {
1536				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1537			}
1538			if received > payable {
1539				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1540					p.CustomerID, m, received, payable)
1541			}
1542		}
1543	
1544		c := &correction{
1545			ID:          corrID,
1546			PaymentID:   payID,
1547			Reason:      reason,
1548			Allocations: allocs,
1549			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1550		}
1551		s.NextSeq++
1552		c.Seq = s.NextSeq
1553		s.Corrections[corrID] = c
1554	
1555		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1556		// 一切不生效，该更正标识不被占用。
1557		if err := s.save(); err != nil {
1558			delete(s.Corrections, corrID)
1559			s.NextSeq--
1560			return err
1561		}
1562		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1563		printCorrection(c, s)
1564		return nil
1565	}
1566	
1567	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1568	func unionMonths(a, b []paymentAllocation) []string {
1569		set := make(map[string]bool, len(a)+len(b))
1570		for _, al := range a {
1571			set[al.Month] = true
1572		}
1573		for _, al := range b {
1574			set[al.Month] = true
1575		}
1576		months := make([]string, 0, len(set))
1577		for m := range set {
1578			months = append(months, m)
1579		}
1580		sort.Strings(months)
1581		return months
1582	}
1583	
1584	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1585	// 新分配，或（首次更正时）收款的原始分配。
1586	func allocationBefore(s *state, c *correction) []paymentAllocation {
1587		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1588		var latest *correction
1589		for _, o := range s.Corrections {
1590			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1591				latest = o
1592			}
1593		}
1594		if latest != nil {
1595			before = latest.Allocations
1596		}
1597		return before
1598	}
1599	
1600	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1601	// 以及前后分配涉及月份的当前余额。
1602	func printCorrection(c *correction, s *state) {
1603		p := s.Payments[c.PaymentID] // 载入时已校验存在
1604		before := allocationBefore(s, c)
1605		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1606		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1607			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1608		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1609		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1610		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1611		fmt.Fprintln(stdout, "涉及月份当前余额：")
1612		for _, m := range unionMonths(before, c.Allocations) {
1613			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1614			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1615			received, _ := paymentReceived(s, p.CustomerID, m)
1616			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1617				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1618				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1619		}
1620	}
1621	
1622	// --- 账后对账流水 ---
1623	
1624	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1625	// 分配更正、撤销收款或退款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1626	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1627	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值；退款在其发生
1628	// 序号减少本账单实收，不可撤销。
1629	type ledgerEvent struct {
1630		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
1631		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款 / 退款
1632		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1633		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1634		deltaReceived int64  // 对实收的影响（分，带符号）
1635		note          string // 原因（调整/更正类）或备注（收款类）
1636		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1637		payTotal      int64  // 收款类事件：汇款总额
1638		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
1639		payID         string // 更正/退款事件：关联收款标识
1640		beforeAlloc   int64  // 更正事件：本账单更正前分配
1641		afterAlloc    int64  // 更正事件：本账单更正后分配
1642		afterPayable  int64  // 事件后的应付（回放时填充）
1643		afterReceived int64  // 事件后的实收（回放时填充）
1644	}
1645	
1646	// billLedger 返回目标账单的一条按操作序号升序的账后流水，事件之后的三项
1647	// 余额已逐步填充。业务归属、金额影响（调整/撤销/收款/更正/撤销收款/退款）
1648	// 与完整性核验都来自与 bill reconcile 共用的 postbill 计算，本处只取该账单
1649	// 那一条流水：
1650	//
1651	//   - 以原总金额为初始应付、零实收为起点；
1652	//   - 回放覆盖完整流水（不受查询截止序号限制），序号重复、撤销先于原操作，
1653	//     或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值，都视为
1654	//     数据异常并拒绝，即使异常发生在截止序号之后——只检查最终余额会放过
1655	//     中间越界的存档；
1656	//   - 曾涉及该账单的收款在被更正移出该月后，仍保留零金额撤销事件。
1657	//
1658	// 只读：不修改库、不占用序号、不新增记录。
1659	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1660		ops, err := postbillOps(s, b.CustomerID)
1661		if err != nil {
1662			return nil, err
1663		}
1664		ledgers, err := verifyPostbillLedgers(ops, []*bill{b})
1665		if err != nil {
1666			return nil, err
1667		}
1668		return ledgers[b.Month], nil
1669	}
1670	
1671	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1672		if !validMonth(month) {
1673			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1674		}
1675		s, err := loadStore(dir)
1676		if err != nil {
1677			return err
1678		}
1679		cust, ok := s.Customers[customerID]
1680		if !ok {
1681			return fmt.Errorf("客户标识 %q 不存在", customerID)
1682		}
1683		b, ok := s.Bills[billKey(customerID, month)]
1684		if !ok {
1685			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1686		}
1687	
1688		// 截止序号使用调整/收款/更正/退款及其撤销共用的已保存全局序号：省略表示最新，
1689		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1690		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1691		cutoff := s.NextSeq
1692		cutoffDesc := "省略，按最新"
1693		if hasCutoff {
1694			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1695			if perr != nil {
1696				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1697			}
1698			if v < 0 {
1699				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1700			}
1701			if v > s.NextSeq {
1702				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1703			}
1704			cutoff = v
1705			cutoffDesc = "指定"
1706		}
1707	
1708		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1709		// 拒绝，不输出部分正常的报告。
1710		events, err := billLedger(s, b)
1711		if err != nil {
1712			return err
1713		}
1714		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1715		return nil
1716	}
1717	
1718	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1719		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1720		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1721		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1722		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1723		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1724		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1725		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1726			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1727	
1728		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1729		payable, received := b.TotalFee, int64(0)
1730		var shown []ledgerEvent
1731		for _, ev := range events {
1732			if ev.seq > cutoff {
1733				continue
1734			}
1735			shown = append(shown, ev)
1736			payable, received = ev.afterPayable, ev.afterReceived
1737		}
1738		if len(shown) == 0 {
1739			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1740		} else {
1741			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1742			for i, ev := range shown {
1743				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1744			}
1745		}
1746		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1747			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1748	}
1749	
1750	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1751	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1752	// 说明汇款总额与本账单分配。
1753	func formatLedgerEvent(ev ledgerEvent) string {
1754		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1755			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1756		switch ev.kind {
1757		case "调整":
1758			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1759				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1760		case "撤销调整":
1761			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1762				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1763		case "收款":
1764			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1765				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1766		case "更正":
1767			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1768				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1769		case "退款":
1770			return fmt.Sprintf("序号 %d 退款 %s：实收 %+d 分（%s，关联收款 %s，本账单退款 %d 分），原因：%s → %s",
1771				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.payAlloc, ev.note, after)
1772		default: // 撤销收款
1773			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1774				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1775		}
1776	}
1777

