1	package main
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// 本文件实现阶梯客户的按月暂停区间：登记（customer suspend）、查询
11	// （customer suspensions）以及暂停的按月提前恢复（customer resume）。
12	// 区间按 UTC 自然月解释为 [起月, 结束月)，包含起月、不包含结束月；暂停月
13	// 不接收用量、不产生月费账单。区间可相接（相接视为连续暂停）但不得重叠，
14	// 不在任何当前有效区间内的月份正常服务。
15	//
16	// 提前恢复只缩短目标暂停的当前有效区间：原暂停区间与原因永久保留，当前有效
17	// 区间改为 [原起月, 恢复月)，恢复月起不再受该项暂停限制；恢复记录永久保留、
18	// 不可改写或撤销，每项暂停只能登记一次。暂停与恢复都不产生账后流水事件，
19	// 也不占用全局操作序号。固定单价客户不适用暂停。
20	
21	func cmdCustomerSuspend(dir, customerID, startMonth, endMonth, reason string) error {
22		if !validMonth(startMonth) {
23			return fmt.Errorf("暂停起月 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", startMonth)
24		}
25		if !validMonth(endMonth) {
26			return fmt.Errorf("暂停结束月 %q 无效，必须是 YYYY-MM 形式（如 2027-02）", endMonth)
27		}
28		if endMonth <= startMonth {
29			return fmt.Errorf("暂停结束月 %s 必须晚于起月 %s（区间包含起月、不包含结束月）", endMonth, startMonth)
30		}
31		if strings.TrimSpace(reason) == "" {
32			return fmt.Errorf("暂停原因不能为空")
33		}
34	
35		s, err := loadStore(dir)
36		if err != nil {
37			return err
38		}
39		cust, ok := s.Customers[customerID]
40		if !ok {
41			return fmt.Errorf("客户标识 %q 不存在", customerID)
42		}
43		if cust.PlanID == "" {
44			return fmt.Errorf("客户 %s 是固定单价客户（单价 %d 分），未绑定阶梯方案，不适用暂停", customerID, cust.Price)
45		}
46	
47		key := suspensionKey(customerID, startMonth)
48		if existing, ok := s.Suspensions[key]; ok {
49			// 一项暂停由客户与起月共同标识：仍按原结束月与原原因判重。相同结束
50			// 月与原因的重放返回原记录且不写盘，不能借重放延长有效暂停——即使
51			// 该项暂停后来已提前恢复（当前有效区间已缩短）；结束月或原因不同
52			// 则拒绝，记录不可改写。
53			if existing.EndMonth == endMonth && existing.Reason == reason {
54				fmt.Fprintf(stdout, "客户 %s 自 %s 起的暂停区间已存在且内容相同，返回原记录（不写盘）：\n\n", customerID, startMonth)
55				printSuspension(existing)
56				return nil
57			}
58			return fmt.Errorf("客户 %s 在 %s 已登记暂停区间（原结束月 %s，原因 %q），内容不同，暂停记录不可改写",
59				customerID, startMonth, existing.EndMonth, existing.Reason)
60		}
61	
62		// 起月须晚于该客户所有已封账月份：已封账账单不因暂停改变。
63		for _, b := range s.Bills {
64			if b.CustomerID == customerID && b.Month >= startMonth {
65				return fmt.Errorf("客户 %s 的 %s 已封账，暂停起月 %s 须晚于该客户所有已封账月份",
66					customerID, b.Month, startMonth)
67			}
68		}
69		// 同一客户的当前有效区间不得重叠（可以相接，相接视为连续暂停）：提前
70		// 恢复只缩短其他暂停的有效区间，故重叠判断使用各项的当前有效结束月；
71		// 其他客户互不影响。
72		for _, su := range s.suspensionsFor(customerID) {
73			effEnd := s.suspensionEffectiveEnd(su)
74			if startMonth < effEnd && endMonth > su.StartMonth {
75				return fmt.Errorf("新区间 %s..%s（不含结束月）与客户 %s 已登记区间 %s..%s（当前有效，不含结束月）重叠；区间可以相接但不得重叠",
76					startMonth, endMonth, customerID, su.StartMonth, effEnd)
77			}
78		}
79		// 登记前检查新区间内已导入的有效（未撤回）用量：存在任一条就拒绝并指出
80		// 冲突记录，不删除或改写任何用量；已撤回记录不参与冲突判断，可存在于
81		// 随后暂停的月份。
82		var conflicts []string
83		conflictMonths := make(map[string]bool)
84		for _, u := range s.Usage {
85			if s.isWithdrawn(u.ID) {
86				continue
87			}
88			if u.CustomerID != customerID {
89				continue
90			}
91			m := utcMonth(u.Time)
92			if monthInRange(m, startMonth, endMonth) {
93				conflicts = append(conflicts, fmt.Sprintf("用量 %s（%s，数量 %d）", u.ID, m, u.Quantity))
94				conflictMonths[m] = true
95			}
96		}
97		if len(conflicts) > 0 {
98			sort.Strings(conflicts)
99			months := make([]string, 0, len(conflictMonths))
100			for m := range conflictMonths {
101				months = append(months, m)
102			}
103			sort.Strings(months)
104			return fmt.Errorf("暂停区间 %s..%s（不含结束月）内已存在 %d 条用量（月份 %s），拒绝登记且不改写用量：%s",
105				startMonth, endMonth, len(conflicts), strings.Join(months, "、"), strings.Join(conflicts, "、"))
106		}
107	
108		su := &suspension{
109			CustomerID: customerID,
110			StartMonth: startMonth,
111			EndMonth:   endMonth,
112			Reason:     reason,
113			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
114		}
115		s.Suspensions[key] = su
116	
117		// 暂停记录整体原子落盘后才报告成功；保存失败则一切不生效，
118		// 该客户该起月不被占用，可原样重试。
119		if err := s.save(); err != nil {
120			delete(s.Suspensions, key)
121			return err
122		}
123		fmt.Fprintf(stdout, "已登记暂停区间：客户 %s 自 %s（UTC 自然月，含）至 %s（不含）暂停服务，期间不接收用量、不产生月费账单：\n\n",
124			customerID, startMonth, endMonth)
125		printSuspension(su)
126		return nil
127	}
128	
129	// cmdCustomerResume 为一项已登记暂停登记按月提前恢复：以客户与原起月识别
130	// 目标暂停，恢复月（UTC 自然月，含）起重新提供服务。原起月 < 恢复月 <
131	// 原结束月；原暂停区间与原因永久保留，当前有效区间缩短为 [原起月, 恢复月)。
132	// 每项暂停只能登记一次提前恢复；相同恢复月与原因的重放返回保存信息与当前
133	// 有效区间、不写盘，内容不同拒绝。其他月份已封账不妨碍登记，已有账单、
134	// 用量、方案安排和账后余额不变，不占用账后操作序号。
135	func cmdCustomerResume(dir, customerID, startMonth, resumeMonth, reason string) error {
136		if !validMonth(startMonth) {
137			return fmt.Errorf("目标暂停原起月 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", startMonth)
138		}
139		if !validMonth(resumeMonth) {
140			return fmt.Errorf("恢复月 %q 无效，必须是 YYYY-MM 形式（如 2026-12）", resumeMonth)
141		}
142		if strings.TrimSpace(reason) == "" {
143			return fmt.Errorf("提前恢复原因不能为空")
144		}
145	
146		s, err := loadStore(dir)
147		if err != nil {
148			return err
149		}
150		cust, ok := s.Customers[customerID]
151		if !ok {
152			return fmt.Errorf("客户标识 %q 不存在", customerID)
153		}
154		if cust.PlanID == "" {
155			return fmt.Errorf("客户 %s 是固定单价客户（单价 %d 分），未绑定阶梯方案，不适用暂停与提前恢复", customerID, cust.Price)
156		}
157	
158		key := suspensionKey(customerID, startMonth)
159		su, ok := s.Suspensions[key]
160		if !ok {
161			return fmt.Errorf("客户 %s 自 %s 起的暂停不存在，无法登记提前恢复（目标暂停必须先以 customer suspend 登记）",
162				customerID, startMonth)
163		}
164		if existing, ok := s.SuspensionResumes[key]; ok {
165			// 以客户和原起月识别该项恢复：相同恢复月与原因的重放返回保存信息
166			// 和当前有效区间、不写盘——即使恢复月后来已结算、又登记了新的暂停
167			// 或发生方案变更也须成功，且不撤销后来的暂停；内容不同拒绝，恢复
168			// 记录不可改写或撤销。
169			if existing.ResumeMonth == resumeMonth && existing.Reason == reason {
170				fmt.Fprintf(stdout, "客户 %s 自 %s 起暂停的提前恢复已存在且内容相同，返回保存信息与当前有效区间（不写盘）：\n\n",
171					customerID, startMonth)
172				printSuspensionDetail(s, su)
173				return nil
174			}
175			return fmt.Errorf("客户 %s 自 %s 起的暂停已登记提前恢复（恢复月 %s，原因 %q），恢复月或原因不同即拒绝；每项暂停只能登记一次提前恢复，恢复记录不可改写或撤销",
176				customerID, startMonth, existing.ResumeMonth, existing.Reason)
177		}
178	
179		// 原起月 < 恢复月 < 原结束月：恢复月必须仍在目标暂停原区间内部，
180		// 月份按 UTC 自然月解释，与操作当天无关。
181		if resumeMonth <= startMonth {
182			return fmt.Errorf("恢复月 %s 必须晚于目标暂停原起月 %s", resumeMonth, startMonth)
183		}
184		if resumeMonth >= su.EndMonth {
185			return fmt.Errorf("恢复月 %s 必须早于目标暂停原结束月 %s（原结束月本就恢复服务，无需提前恢复）",
186				resumeMonth, su.EndMonth)
187		}
188	
189		r := &suspensionResume{
190			CustomerID:  customerID,
191			StartMonth:  startMonth,
192			ResumeMonth: resumeMonth,
193			Reason:      reason,
194			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
195		}
196		s.SuspensionResumes[key] = r
197	
198		// 恢复记录整体原子保存后才报告成功；保存失败则一切不生效，不占用该项
199		// 暂停的恢复登记，可原样重试。提前恢复只缩短目标区间，不改动用量、账单、
200		// 方案安排、账后余额或其他暂停。
201		if err := s.save(); err != nil {
202			delete(s.SuspensionResumes, key)
203			return err
204		}
205		fmt.Fprintf(stdout, "已登记暂停提前恢复：客户 %s 的暂停自 %s（UTC 自然月，含）起恢复服务，无需等到原结束月 %s；原暂停区间与原因永久保留，恢复记录不可改写或撤销：\n\n",
206			customerID, resumeMonth, su.EndMonth)
207		printSuspensionDetail(s, su)
208		return nil
209	}
210	
211	// printSuspension 输出一条暂停区间的原区间与原因（customer suspend 登记
212	// 与相同重放使用）。提前恢复信息由 printSuspensionDetail 展示。
213	func printSuspension(su *suspension) {
214		fmt.Fprintf(stdout, "客户：%s\n", su.CustomerID)
215		fmt.Fprintf(stdout, "暂停区间：%s（含）至 %s（不含，UTC 自然月）\n", su.StartMonth, su.EndMonth)
216		fmt.Fprintf(stdout, "原因：%s\n", su.Reason)
217	}
218	
219	// printSuspensionDetail 输出一项暂停的完整信息：原暂停区间与原因、提前恢复
220	// 信息（若有）以及当前有效区间。原区间与原因永久保留；当前有效区间在提前
221	// 恢复后缩短为 [原起月, 恢复月)。
222	func printSuspensionDetail(s *state, su *suspension) {
223		fmt.Fprintf(stdout, "客户：%s\n", su.CustomerID)
224		fmt.Fprintf(stdout, "原暂停区间：%s（含）至 %s（不含，UTC 自然月，永久保留）\n", su.StartMonth, su.EndMonth)
225		fmt.Fprintf(stdout, "原暂停原因：%s（永久保留）\n", su.Reason)
226		effEnd := s.suspensionEffectiveEnd(su)
227		if r := s.suspensionResumeOf(su); r != nil {
228			fmt.Fprintf(stdout, "提前恢复：自 %s（含，UTC 自然月）起恢复服务，恢复原因：%s（恢复记录永久保留、不可改写或撤销）\n",
229				r.ResumeMonth, r.Reason)
230			fmt.Fprintf(stdout, "当前有效区间：%s（含）至 %s（不含，恢复月起不再受该项暂停限制；仍暂停的月份不补收月费）\n",
231				su.StartMonth, effEnd)
232		} else {
233			fmt.Fprintln(stdout, "提前恢复：无")
234			fmt.Fprintf(stdout, "当前有效区间：%s（含）至 %s（不含，与原暂停区间相同）\n", su.StartMonth, effEnd)
235		}
236	}
237	
238	// describeSuspension 返回覆盖指定月份的暂停当前有效区间的简短描述，用于
239	// 错误信息。
240	func describeSuspension(s *state, customerID, month string) string {
241		for _, su := range s.suspensionsFor(customerID) {
242			effEnd := s.suspensionEffectiveEnd(su)
243			if monthInRange(month, su.StartMonth, effEnd) {
244				return fmt.Sprintf("有效区间 %s（含）至 %s（不含），原因：%s", su.StartMonth, effEnd, su.Reason)
245			}
246		}
247		return "暂停区间"
248	}
249	
250	func cmdCustomerSuspensions(dir, customerID, month string, hasMonth bool) error {
251		if hasMonth && !validMonth(month) {
252			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-11）", month)
253		}
254	
255		s, err := loadStore(dir)
256		if err != nil {
257			return err
258		}
259		cust, ok := s.Customers[customerID]
260		if !ok {
261			return fmt.Errorf("客户标识 %q 不存在", customerID)
262		}
263	
264		// 只读查询：不改写存档、不占用序号、不新增记录；成功或失败均不落盘。
265		if cust.PlanID == "" {
266			fmt.Fprintf(stdout, "客户 %s（%s）是固定单价客户（单价 %d 分），不适用按月暂停，全部月份正常服务\n",
267				cust.ID, cust.Name, cust.Price)
268			if hasMonth {
269				fmt.Fprintf(stdout, "月份 %s：不适用暂停（固定单价客户正常服务）\n", month)
270			}
271			return nil
272		}
273	
274		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
275		list := s.suspensionsFor(customerID)
276		if len(list) == 0 {
277			fmt.Fprintln(stdout, "暂停区间：无（全部 UTC 自然月正常服务）")
278		} else {
279			fmt.Fprintln(stdout, "暂停区间（按起月升序；原区间与原因永久保留，另展示提前恢复信息与当前有效区间）：")
280			for i, su := range list {
281				effEnd := s.suspensionEffectiveEnd(su)
282				fmt.Fprintf(stdout, "  %d. %s（含）至 %s（不含），原因：%s\n",
283					i+1, su.StartMonth, su.EndMonth, su.Reason)
284				if r := s.suspensionResumeOf(su); r != nil {
285					fmt.Fprintf(stdout, "     提前恢复：自 %s（含，UTC 自然月）起恢复服务，恢复原因：%s（永久保留、不可改写或撤销）\n",
286						r.ResumeMonth, r.Reason)
287					fmt.Fprintf(stdout, "     当前有效区间：%s（含）至 %s（不含，恢复月起正常服务）\n", su.StartMonth, effEnd)
288				} else {
289					fmt.Fprintf(stdout, "     提前恢复：无；当前有效区间：%s（含）至 %s（不含，与原区间相同）\n",
290						su.StartMonth, effEnd)
291				}
292			}
293		}
294		if hasMonth {
295			var hit *suspension
296			for _, su := range list {
297				if monthInRange(month, su.StartMonth, s.suspensionEffectiveEnd(su)) {
298					hit = su
299					break
300				}
301			}
302			if hit != nil {
303				r := s.suspensionResumeOf(hit)
304				fmt.Fprintf(stdout, "月份 %s：已暂停（处于当前有效区间 %s（含）至 %s（不含）），原暂停原因：%s",
305					month, hit.StartMonth, s.suspensionEffectiveEnd(hit), hit.Reason)
306				if r != nil {
307					// 当前有效区间内的月份不可能晚于恢复月；保留恢复信息以便核对。
308					fmt.Fprintf(stdout, "；该暂停已登记自 %s（含）起提前恢复", r.ResumeMonth)
309				}
310				fmt.Fprintln(stdout)
311			} else {
312				// 实际未暂停时区分：原本在暂停原区间内但因提前恢复而释放的月份，
313				// 与从未被任何暂停覆盖的月份。
314				var released *suspension
315				for _, su := range list {
316					if r := s.suspensionResumeOf(su); r != nil &&
317						monthInRange(month, su.StartMonth, su.EndMonth) && month >= r.ResumeMonth {
318						released = su
319						break
320					}
321				}
322				if released != nil {
323					r := s.suspensionResumeOf(released)
324					fmt.Fprintf(stdout, "月份 %s：未暂停（原暂停 %s（含）至 %s（不含）已登记提前恢复，自 %s（含）起恢复服务，恢复原因：%s，正常服务）\n",
325						month, released.StartMonth, released.EndMonth, r.ResumeMonth, r.Reason)
326				} else {
327					fmt.Fprintf(stdout, "月份 %s：未暂停（不在任何暂停当前有效区间内，正常服务）\n", month)
328				}
329			}
330		}
331		return nil
332	}
