1	package main
2	
3	import (
4		"fmt"
5		"strconv"
6		"strings"
7		"time"
8	)
9	
10	// 本文件实现未封账用量的原子更正（usage correct）：用一条全新记录替代错误
11	// 的客户、时间或数量，并永久保留来源。固定单价与阶梯客户均适用。
12	//
13	// 首次更正要求原记录存在且未撤回、按原时间换算的 UTC 自然月未封账；新标识
14	// 非空、不同于原标识且从未使用（已有同内容记录也不能充当替代记录）；新客户
15	// 须存在，新时间对应的 UTC 自然月未封账且未暂停。数量按新客户固定单价或
16	// 该月有效阶梯方案做单条从零计价预检，全程整数计算并检查溢出；月累计溢出
17	// 仍由结算把关。
18	//
19	// 成功时原记录按更正原因标记撤回、登记替代记录并永久保存关联，三项在同一
20	// 次原子保存中落盘后才报告成功；原内容不可改写，更正不可撤销，不占用账后
21	// 操作序号。任一步失败都非零退出并说明原因，全部业务状态不变，不占新标识，
22	// 可原样重试。
23	//
24	// 每条原用量只能更正一次，以原标识识别该项更正。相同新标识、客户、解析后
25	// 的时间点、数量与原因重放，返回原更正及两条记录当前状态，不写盘；任一项
26	// 不同拒绝。替代记录可继续更正或按原规则撤回；后来封账、暂停、方案变化或
27	// 替代记录已撤回，都不能阻止相同重放，也不能恢复任何记录。
28	
29	func cmdUsageCorrect(dir, origID, newID, newCustomerID, newTimeText, qtyText, reason string) error {
30		if strings.TrimSpace(origID) == "" {
31			return fmt.Errorf("原用量标识不能为空")
32		}
33		if strings.TrimSpace(newID) == "" {
34			return fmt.Errorf("新用量标识不能为空")
35		}
36		if strings.TrimSpace(newCustomerID) == "" {
37			return fmt.Errorf("新客户标识不能为空")
38		}
39		if strings.TrimSpace(reason) == "" {
40			return fmt.Errorf("更正原因不能为空")
41		}
42		t, err := time.Parse(time.RFC3339, strings.TrimSpace(newTimeText))
43		if err != nil {
44			return fmt.Errorf("新时间 %q 不是 RFC3339 格式：%w", newTimeText, err)
45		}
46		qty, err := strconv.ParseInt(strings.TrimSpace(qtyText), 10, 64)
47		if err != nil {
48			return fmt.Errorf("新数量 %q 不是有符号 64 位整数: %w", qtyText, err)
49		}
50		if qty <= 0 {
51			return fmt.Errorf("新数量必须是正整数，收到 %d", qty)
52		}
53	
54		s, err := loadStore(dir)
55		if err != nil {
56			return err
57		}
58	
59		// 幂等重放优先于一切首次校验：以原标识识别该项更正。后来封账、暂停、
60		// 方案变化或替代记录已撤回，都不能阻止相同重放，也不能恢复任何记录。
61		if uc, ok := s.UsageCorrections[origID]; ok {
62			if uc.ReplacementID == newID && uc.NewCustomerID == newCustomerID &&
63				uc.NewQuantity == qty && uc.Reason == reason {
64				savedT, perr := time.Parse(time.RFC3339, uc.NewTime)
65				if perr == nil && savedT.Equal(t) {
66					fmt.Fprintf(stdout, "用量 %q 的更正已存在且内容相同，返回原更正及两条记录当前状态（不写盘）：\n\n", origID)
67					printUsageCorrection(s, uc)
68					return nil
69				}
70			}
71			return fmt.Errorf("用量 %q 已更正（替代记录 %q，客户 %s，时间 %s，数量 %d，原因 %q），"+
72				"新标识、客户、解析后的时间点、数量或原因任一项不同即拒绝；每条原用量只能更正一次，更正不可撤销",
73				origID, uc.ReplacementID, uc.NewCustomerID, uc.NewTime, uc.NewQuantity, uc.Reason)
74		}
75	
76		orig, ok := s.Usage[origID]
77		if !ok {
78			return fmt.Errorf("原用量标识 %q 不存在，无法更正", origID)
79		}
80		// 已撤回（含被其他更正替代，该项已在上面按重放处理）的记录不能再更正；
81		// 更正只能作用于一条仍有效的原记录。
82		if s.isWithdrawn(origID) {
83			w := s.Withdrawals[origID]
84			return fmt.Errorf("原用量 %q 已撤回（撤回原因 %q），不能更正；撤回不可恢复", origID, w.Reason)
85		}
86		origMonth := utcMonth(orig.Time)
87		if s.sealed(orig.CustomerID, origMonth) {
88			return fmt.Errorf("原用量 %q 属于客户 %s 的 %s（UTC 自然月），该月已封账，拒绝更正；账单与账后余额不变",
89				origID, orig.CustomerID, origMonth)
90		}
91	
92		if newID == origID {
93			return fmt.Errorf("新用量标识 %q 与原用量标识相同，替代记录必须使用全新标识", newID)
94		}
95		if _, used := s.Usage[newID]; used {
96			// 标识从未使用：即使已有一条客户、时间、数量完全相同的记录，也不能
97			// 让它充当替代记录。
98			return fmt.Errorf("新用量标识 %q 已被使用，替代记录必须使用从未使用的全新标识（已有同内容记录也不能充当替代记录）", newID)
99		}
100		newCust, ok := s.Customers[newCustomerID]
101		if !ok {
102			return fmt.Errorf("新客户标识 %q 不存在", newCustomerID)
103		}
104		newMonth := t.UTC().Format("2006-01")
105		if s.sealed(newCustomerID, newMonth) {
106			return fmt.Errorf("新用量属于客户 %s 的 %s（UTC 自然月），该月已封账，拒绝更正", newCustomerID, newMonth)
107		}
108		if s.isSuspendedMonth(newCustomerID, newMonth) {
109			return fmt.Errorf("新用量属于客户 %s 的 %s（UTC 自然月），该月处于暂停区间（%s），暂停服务期间不接收用量，拒绝更正",
110				newCustomerID, newMonth, describeSuspension(s, newCustomerID, newMonth))
111		}
112	
113		// 单条从零计价预检：固定单价检查 数量×单价；阶梯客户按新时间换算的
114		// UTC 月份的有效方案计价，检查分段金额不溢出。月累计溢出仍由结算把关。
115		repl := &usageRecord{ID: newID, CustomerID: newCustomerID, Time: strings.TrimSpace(newTimeText), Quantity: qty}
116		if newCust.PlanID == "" {
117			if _, err := mul64(qty, newCust.Price); err != nil {
118				return fmt.Errorf("新数量 %d × 客户 %s 单价 %d 金额溢出有符号 64 位整数范围，拒绝更正",
119					qty, newCustomerID, newCust.Price)
120			}
121		} else {
122			planID := s.effectivePlanID(newCust, newMonth)
123			if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{repl}); err != nil {
124				return fmt.Errorf("按客户 %s 的 %s 月有效方案 %q 对新数量单条从零计价失败：%v；拒绝更正",
125					newCustomerID, newMonth, planID, err)
126			}
127		}
128	
129		// 三项变更先在内存完成，再整体原子保存：原记录撤回标记、替代记录、
130		// 更正关联。原内容不改写，不占用账后操作序号。
131		now := time.Now().UTC().Format(time.RFC3339)
132		s.Withdrawals[origID] = &withdrawal{UsageID: origID, Reason: reason, CreatedAt: now}
133		s.Usage[newID] = repl
134		uc := &usageCorrection{
135			UsageID:       origID,
136			ReplacementID: newID,
137			NewCustomerID: newCustomerID,
138			NewTime:       repl.Time,
139			NewQuantity:   qty,
140			Reason:        reason,
141			CreatedAt:     now,
142		}
143		s.UsageCorrections[origID] = uc
144	
145		if err := s.save(); err != nil {
146			// 保存失败：三项全部回滚，全部业务状态不变，失败不占用新标识，
147			// 原记录不留下撤回标记或关联，可原样重试。
148			delete(s.Withdrawals, origID)
149			delete(s.Usage, newID)
150			delete(s.UsageCorrections, origID)
151			return err
152		}
153	
154		fmt.Fprintf(stdout, "已更正用量 %q：原记录按更正原因标记撤回，替代记录 %q 已登记，关联永久保存；原内容不可改写、更正不可撤销、不占用账后操作序号：\n\n",
155			origID, newID)
156		printUsageCorrection(s, uc)
157		return nil
158	}
159	
160	// predecessorCorrection 返回以指定用量为替代记录的更正（即该记录的直接
161	// 前身关联）；无前身时返回 nil。
162	func predecessorCorrection(s *state, usageID string) *usageCorrection {
163		for _, uc := range s.UsageCorrections {
164			if uc.ReplacementID == usageID {
165				return uc
166			}
167		}
168		return nil
169	}
170	
171	// successorCorrection 返回指定用量作为原记录的更正（即该记录的直接后继
172	// 关联）；无后继时返回 nil。
173	func successorCorrection(s *state, usageID string) *usageCorrection {
174		return s.UsageCorrections[usageID]
175	}
176	
177	// printUsageCorrection 输出一项用量更正：更正原因、原记录与替代记录的完整
178	// 内容、各自 UTC 月份与当前状态，以及二者的替代关联。记录状态取当前库状态：
179	// 替代记录可能已被继续更正或撤回，原记录始终保持已撤回。
180	func printUsageCorrection(s *state, uc *usageCorrection) {
181		fmt.Fprintf(stdout, "更正原因：%s\n", uc.Reason)
182		orig := s.Usage[uc.UsageID]       // 载入时已校验存在
183		repl := s.Usage[uc.ReplacementID] // 载入时已校验存在
184		fmt.Fprintln(stdout, "原记录（已按更正原因标记撤回，原内容永久保留、不可改写）：")
185		printUsageRecord(s, orig)
186		fmt.Fprintln(stdout)
187		fmt.Fprintln(stdout, "替代记录（全新标识，承载更正后的客户、时间与数量）：")
188		printUsageRecord(s, repl)
189		fmt.Fprintln(stdout)
190		fmt.Fprintf(stdout, "关联：%s（%s，UTC 月份 %s）→ %s（%s，UTC 月份 %s），原因：%s；更正不可撤销\n",
191			orig.ID, orig.CustomerID, utcMonth(orig.Time),
192			repl.ID, repl.CustomerID, utcMonth(repl.Time), uc.Reason)
193	}
