			fmt.Fprintf(stdout, "  %d. 自 %s 起改用 %s（%s）：月费 %d 分，规则 %s，原因：%s\n",
				i+1, ch.Month, p.ID, p.Name, p.MonthlyFee, formatTiers(p.Tiers), ch.Reason)
		}
	}
}

